// Writes src/generated/rts-bundle.ts — the deployable RTS source as a string
// constant, embedded by every downstream bundle (the npm CLI, the SEA binary)
// so packaged builds can deploy without a dist/rts.js or package manifest on
// disk. Runs in the `build` script after the rts config produced dist/rts.js.
// The output is gitignored; a committed `.d.ts` stub next to it keeps
// `#/generated/rts-bundle` type-resolvable on a fresh clone.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const packageRoot = resolve(import.meta.dirname, '..');
const bundlePath = resolve(packageRoot, 'dist', 'rts.js');
const out = resolve(packageRoot, 'src', 'generated', 'rts-bundle.ts');

let source;
try {
  source = readFileSync(bundlePath, 'utf-8');
} catch (error) {
  throw new Error(
    `RTS bundle not found at ${bundlePath} — the rts build (tsdown.rts.config.ts) must run first.`,
    { cause: error },
  );
}
if (source.length < 1024) {
  throw new Error(`RTS bundle at ${bundlePath} looks invalid (${source.length} bytes)`);
}

mkdirSync(dirname(out), { recursive: true });
writeFileSync(
  out,
  '// GENERATED by scripts/gen-rts-bundle.mjs — do not edit.\n' +
    `export const RTS_BUNDLE_SOURCE = ${JSON.stringify(source)};\n`,
);
console.log(`[gen-rts-bundle] wrote ${out} (${(source.length / 1024).toFixed(1)} KB source)`);
